const entradas = $input.all();
const consultas = $("Generar consultas Magneto").all();
const fechaExtraccion = new Date().toISOString();
const vacantesUnicas = new Map();

function texto(valor) {
  return String(valor ?? "").trim();
}

function normalizar(valor) {
  return texto(valor)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function obtenerDetalleModalidad(entrada, indiceTarjeta, cargo) {
  const detalles = entrada.result?.vacancy_details || [];
  const detalleIndice = detalles[indiceTarjeta];
  if (detalleIndice && normalizar(detalleIndice.title) === normalizar(cargo)) return detalleIndice;
  return detalles.find(detalle => normalizar(detalle.title) === normalizar(cargo)) || {
    url: "",
    modalidad_trabajo: "No disponible",
    modalidad_texto_original: "",
    estado_modalidad: "Detalle no localizado"
  };
}

function combinarValores(valorActual, valorNuevo) {
  const valores = new Set(texto(valorActual).split(" | ").filter(Boolean));
  if (valorNuevo !== undefined && valorNuevo !== null && valorNuevo !== "") {
    valores.add(String(valorNuevo));
  }
  return [...valores].join(" | ");
}

function clasificarNivel(cargo, contrato) {
  const valor = normalizar(`${cargo} ${contrato}`);
  if (/practic|aprendiz|contrato de aprendizaje|estudiante en practica/.test(valor)) return "Práctica o aprendizaje";
  if (/director|gerente|vicepresidente|decano|rector/.test(valor)) return "Directivo";
  if (/coordinador|jefe|lider|especialista|consultor senior/.test(valor)) return "Coordinación o especialista";
  if (/auxiliar|operario|operador|bodeguero|oficios varios|conductor/.test(valor)) return "Auxiliar u operativo";
  if (/tecnico|tecnologo/.test(valor)) return "Técnico o tecnólogo";
  if (/profesional|ingenier|agronom|cientific|abogad|psicolog|medic|enfermer|analista|docente|profesor|investigador|desarrollador|comunicador|trabajador social/.test(valor)) return "Profesional";
  return "No determinado";
}

function clasificarAreaRegional(cargo) {
  const valor = normalizar(cargo);
  const reglas = [
    ["AE10", "Seguridad y salud en el trabajo", /\bsst\b|seguridad y salud/],
    ["AE03", "Inteligencia artificial, datos y ciberseguridad", /inteligencia artificial|analitica|analista de datos|ciberseguridad|business intelligence|cientifico de datos/],
    ["AE02", "Tecnologías digitales y software", /software|desarrollador|programador|sistemas|devops|cloud|soporte ti/],
    ["AE11", "Ambiente, sostenibilidad y cambio climático", /ambiental|sostenibilidad|forestal|cambio climatico/],
    ["AE12", "Bioeconomía, agroindustria y desarrollo rural", /agronom|agro|agricol|pecuario|rural/],
    ["AE13", "Ciencias básicas e investigación", /investigacion|cientific|laboratorio|biolog|quimic|fisic/],
    ["AE01", "Educación y pedagogía", /docente|profesor|educacion|pedagog|academico/],
    ["AE05", "Infraestructura, construcción y territorio", /ingenieria civil|ingeniero civil|arquitect|construccion|obra/],
    ["AE04", "Ingeniería, automatización e industria", /ingenier|automatizacion|produccion|mantenimiento|manufactura/],
    ["AE09", "Salud, psicología y bienestar", /medic|enfermer|psicolog|fisioter|terapeuta|salud|farmac/],
    ["AE08", "Derecho, gobierno y políticas públicas", /abogad|juridic|legal|derecho/],
    ["AE14", "Desarrollo social y comunitario", /trabajo social|gestor social|comunitari/],
    ["AE15", "Comunicación, diseño e industrias creativas", /comunic|disen|audiovisual|periodis|publicista/],
    ["AE16", "Logística, transporte y cadena de suministro", /logistic|bodega|transporte|conductor|inventario/],
    ["AE17", "Turismo, cultura y servicios", /turismo|hotel|viaje|gastronom|cultura/],
    ["AE18", "Gestión de proyectos, calidad e innovación", /proyecto|calidad|innovacion|transformacion/],
    ["AE06", "Administración, finanzas y economía", /financier|contab|tesorer|administrativ|econom|cartera/],
    ["AE07", "Mercadeo, ventas y emprendimiento", /marketing|mercadeo|comercial|ventas|vendedor|asesor/],
  ];
  for (const [codigo, area, patron] of reglas) {
    if (patron.test(valor)) return { codigo, area };
  }
  return { codigo: "OTR", area: "Otros perfiles regionales" };
}

function extraerSalario(salario) {
  const numeros = texto(salario).match(/\d[\d. ]*/g) || [];
  const valores = numeros
    .map(numero => Number(numero.replace(/[. ]/g, "")))
    .filter(numero => Number.isFinite(numero));
  if (valores.length === 0) return { minimo: null, maximo: null };
  return { minimo: valores[0], maximo: valores[1] ?? valores[0] };
}

function extraerCupos(contenido) {
  const coincidencia = contenido.match(/([\d.,]+)\s+cupos/i);
  if (!coincidencia) return "";
  return coincidencia[1].replace(/[.,]/g, "");
}

const camposCombinables = [
  "id_consulta", "area_codigo", "area_estrategica", "area_origen",
  "subarea", "palabra_clave", "prioridad", "alcance_geografico",
  "pagina_origen", "url_fuente", "url_vacante", "nivel_ocupacional", "cupos_consulta"
];

for (let numeroEntrada = 0; numeroEntrada < entradas.length; numeroEntrada++) {
  const entrada = entradas[numeroEntrada].json;
  const consulta = consultas[numeroEntrada]?.json || {};
  const contenido = entrada.result?.content;
  if (!contenido) continue;

  const lineas = contenido.split(/\r?\n/).map(linea => linea.trim()).filter(Boolean);
  let dentroDeOfertas = false;
  let indiceTarjeta = 0;

  for (let i = 0; i < lineas.length; i++) {
    const linea = lineas[i];
    if (/^#\s+(Ofertas de (empleo|trabajo)|Trabajos en)/i.test(linea)) {
      dentroDeOfertas = true;
      continue;
    }
    if (!dentroDeOfertas) continue;
    if (/^-\s*1$/.test(linea)) break;

    if (linea.startsWith("## ") && !linea.startsWith("### ") && lineas[i + 1]?.startsWith("### ")) {
      const cargo = linea.replace(/^##\s*/, "").trim();
      const datosEmpresa = lineas[i + 1].replace(/^###\s*/, "").trim();
      const separacion = datosEmpresa.lastIndexOf("|");
      const empresa = separacion >= 0 ? datosEmpresa.slice(0, separacion).trim() : datosEmpresa;
      const contrato = separacion >= 0 ? datosEmpresa.slice(separacion + 1).trim() : "";
      const salario = (lineas[i + 2] || "").replace(/,$/, "").trim();
      const ubicacion = lineas[i + 3] || "";
      const urgente = lineas[i + 4]?.toLowerCase() === "requerido con urgencia";
      const detalleModalidad = obtenerDetalleModalidad(entrada, indiceTarjeta, cargo);
      indiceTarjeta += 1;
      const regional = consulta.area_codigo === "REG";
      const clasificacion = regional
        ? clasificarAreaRegional(cargo)
        : { codigo: consulta.area_codigo || "", area: consulta.area_estrategica || "Sin clasificar" };
      const salarioNumerico = extraerSalario(salario);

      const vacante = {
        fecha_extraccion: fechaExtraccion,
        estado_consulta: "Exitosa con vacantes",
        id_consulta: consulta.id_consulta || "",
        area_codigo: clasificacion.codigo,
        area_estrategica: clasificacion.area,
        area_origen: consulta.area_estrategica || "",
        subarea: consulta.subarea || "",
        palabra_clave: consulta.palabra_clave || "",
        prioridad: consulta.prioridad || "",
        alcance_geografico: consulta.alcance_geografico || "Nacional",
        pagina_origen: String(consulta.pagina || 1),
        fuente_portal: consulta.fuente_portal || "Magneto",
        url_fuente: entrada.url || consulta.url || "",
        url_vacante: detalleModalidad.url || "",
        cupos_consulta: extraerCupos(contenido),
        cargo,
        nivel_ocupacional: clasificarNivel(cargo, contrato),
        empresa,
        contrato,
        modalidad_trabajo: detalleModalidad.modalidad_trabajo || "No disponible",
        modalidad_texto_original: detalleModalidad.modalidad_texto_original || "",
        estado_modalidad: detalleModalidad.estado_modalidad || "Detalle no localizado",
        salario,
        salario_minimo: salarioNumerico.minimo,
        salario_maximo: salarioNumerico.maximo,
        ubicacion,
        es_ibague_tolima: /ibagu[eé]|tolima/i.test(ubicacion) || regional,
        urgente
      };

      const clave = [normalizar(cargo), normalizar(empresa), normalizar(ubicacion)].join("|");
      if (vacantesUnicas.has(clave)) {
        const existente = vacantesUnicas.get(clave);
        for (const campo of camposCombinables) {
          existente[campo] = combinarValores(existente[campo], vacante[campo]);
        }
        if (existente.estado_modalidad !== "Publicada" && vacante.estado_modalidad === "Publicada") {
          existente.modalidad_trabajo = vacante.modalidad_trabajo;
          existente.modalidad_texto_original = vacante.modalidad_texto_original;
          existente.estado_modalidad = vacante.estado_modalidad;
          existente.url_vacante = vacante.url_vacante || existente.url_vacante;
        }
        existente.es_ibague_tolima = existente.es_ibague_tolima || vacante.es_ibague_tolima;
        existente.urgente = existente.urgente || urgente;
      } else {
        vacantesUnicas.set(clave, vacante);
      }
    }
  }
}

const vacantes = [...vacantesUnicas.values()];
if (vacantes.length === 0) throw new Error("No se identificaron vacantes en las respuestas recibidas");
return vacantes.map(vacante => ({ json: vacante }));

const entradas = $input.all();
const consultas = $("Generar consultas Magneto").all();
const fechaEjecucion = new Date().toISOString();
const firmasPorConsulta = new Map();

function normalizar(valor) {
  return String(valor ?? "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function obtenerTarjetas(contenido) {
  const lineas = String(contenido || "")
    .split(/\r?\n/)
    .map(linea => linea.trim())
    .filter(Boolean);
  const tarjetas = [];
  let dentroDeOfertas = false;

  for (let i = 0; i < lineas.length; i++) {
    const linea = lineas[i];
    if (/^#\s+(Ofertas de (empleo|trabajo)|Trabajos en)/i.test(linea)) {
      dentroDeOfertas = true;
      continue;
    }
    if (!dentroDeOfertas) continue;
    if (/^-\s*1$/.test(linea)) break;

    if (linea.startsWith("## ") && !linea.startsWith("### ") && lineas[i + 1]?.startsWith("### ")) {
      tarjetas.push(`${normalizar(linea)}|${normalizar(lineas[i + 1])}`);
    }
  }
  return tarjetas;
}

function crearFirma(tarjetas) {
  const texto = tarjetas.join("||");
  let hash = 2166136261;
  for (let i = 0; i < texto.length; i++) {
    hash ^= texto.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, "0");
}

return entradas.map((item, indice) => {
  const entrada = item.json || {};
  const consulta = consultas[indice]?.json || {};
  const contenido = entrada.result?.content || "";
  const tarjetas = obtenerTarjetas(contenido);
  const detalles = entrada.result?.vacancy_details || [];
  const modalidadesPublicadas = detalles.filter(detalle => detalle.estado_modalidad === "Publicada").length;
  const detallesConError = detalles.filter(detalle => detalle.estado_modalidad === "Error de consulta").length;
  const cupos = contenido.match(/([\d.,]+)\s+cupos/i)?.[1] || "";
  const sinPaginaAdicional = entrada.status === "no_additional_page";
  const fallida = !sinPaginaAdicional && !contenido;
  const firma = tarjetas.length > 0 ? crearFirma(tarjetas) : "";
  const firmasAnteriores = firmasPorConsulta.get(consulta.id_consulta) || new Set();
  const paginaRepetida = consulta.pagina > 1 && firma !== "" && firmasAnteriores.has(firma);
  if (firma) firmasAnteriores.add(firma);
  firmasPorConsulta.set(consulta.id_consulta, firmasAnteriores);

  let estado;
  let validacionPaginacion;

  if (sinPaginaAdicional) {
    estado = "Sin página adicional";
    validacionPaginacion = "Sin página adicional";
  } else if (fallida) {
    estado = "Fallida";
    validacionPaginacion = "Fallida";
  } else if (tarjetas.length === 0) {
    estado = "Exitosa sin vacantes";
    validacionPaginacion = consulta.pagina === 1 ? "Página base sin vacantes" : "Sin vacantes";
  } else {
    estado = "Exitosa con vacantes";
    validacionPaginacion = consulta.pagina === 1
      ? "Página base"
      : paginaRepetida
        ? "Repetida"
        : "Contenido diferente";
  }

  return {
    json: {
      fecha_ejecucion: fechaEjecucion,
      id_consulta: consulta.id_consulta || "",
      area_codigo: consulta.area_codigo || "",
      area_estrategica: consulta.area_estrategica || "",
      subarea: consulta.subarea || "",
      alcance_geografico: consulta.alcance_geografico || "",
      pagina: consulta.pagina || 1,
      url: consulta.url || "",
      estado,
      tarjetas_detectadas: tarjetas.length,
      detalles_detectados: detalles.length,
      modalidades_publicadas: modalidadesPublicadas,
      detalles_con_error: detallesConError,
      cupos_publicados: cupos,
      firma_pagina: firma,
      pagina_repetida: paginaRepetida,
      validacion_paginacion: validacionPaginacion,
      mensaje: entrada.message || entrada.error?.message || entrada.error || (fallida ? "Sin respuesta del agente" : "Respuesta recibida")
    }
  };
});

const vacancies = $("Consolidar vacantes multifuente").all().map(item => item.json);
const executions = $("Consolidar control multifuente").all().map(item => item.json);

if (vacancies.length === 0) throw new Error("No hay vacantes para estructurar");
if (executions.length === 0) throw new Error("No hay registros de control para estructurar");

return [{ json: { vacancies, executions } }];

const vacancies = $input.all().map(item => item.json);
if (vacancies.length === 0) throw new Error("No hay vacantes para enriquecer");
return [{ json: { vacancies } }];

const vacancies = $json.vacancies;
if (!Array.isArray(vacancies) || vacancies.length === 0) throw new Error("El servidor no devolvió vacantes enriquecidas");
return vacancies.map(vacancy => ({ json: vacancy }));

const magneto = $("Generar consultas Magneto").all().map(item => item.json);
const catalogo = new Map();
for (const consulta of magneto) {
  if (!catalogo.has(consulta.id_consulta)) catalogo.set(consulta.id_consulta, consulta);
}

function slug(valor) {
  return String(valor || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

const rutasEspeciales = {
  REG01: "ibague",
  REG02: "trabajo-tolima",
  Q043: "trabajo-sostenibilidad",
  Q047: "trabajo-agronomo",
  Q051: "trabajo-cientifico",
  Q052: "trabajo-director-de-investigacion"
};

const consultas = [...catalogo.values()].map(base => {
  const ruta = rutasEspeciales[base.id_consulta] || "trabajo-" + slug(base.palabra_clave);
  return {
    id_consulta: "EE-" + base.id_consulta,
    area_codigo: base.area_codigo,
    area_estrategica: base.area_estrategica,
    subarea: base.subarea,
    palabra_clave: base.palabra_clave,
    prioridad: base.prioridad,
    alcance_geografico: base.alcance_geografico,
    pagina: 1,
    fuente_portal: "elempleo.com",
    url: "https://www.elempleo.com/co/ofertas-empleo/" + ruta
  };
});

return consultas.map(consulta => ({ json: consulta }));

const respuestas = $input.all().map(item => item.json);
const consultas = $("Generar consultas elempleo").all().map(item => item.json);
const unicas = new Map();

function texto(valor) { return String(valor ?? "").trim(); }
function normalizar(valor) {
  return texto(valor).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, " ").trim();
}
function combinar(actual, nuevo) {
  const valores = new Set(texto(actual).split(" | ").filter(Boolean));
  if (texto(nuevo)) valores.add(texto(nuevo));
  return [...valores].join(" | ");
}
function nivel(cargo, descripcion, contrato) {
  const titulo = normalizar(cargo + " " + contrato);
  if (/practic|aprendiz/.test(titulo)) return "Práctica o aprendizaje";
  if (/director|gerente|vicepresidente|decano|rector/.test(titulo)) return "Directivo";
  if (/coordinador|jefe|lider|especialista|consultor senior/.test(titulo)) return "Coordinación o especialista";
  if (/auxiliar|operario|operador|bodeguero|oficios varios|conductor|mensajero/.test(titulo)) return "Auxiliar u operativo";
  if (/tecnico|tecnologo/.test(titulo)) return "Técnico o tecnólogo";
  if (/profesional|ingenier|analista|docente|abogad|psicolog|administrador|contador|medic|enfermer|desarrollador/.test(titulo)) return "Profesional";

  const detalle = normalizar(descripcion);
  const niveles = [
    /bachiller/.test(detalle),
    /tecnico|tecnologo/.test(detalle),
    /profesional|pregrado|universitari/.test(detalle)
  ].filter(Boolean).length;
  if (niveles >= 2) return "Múltiples niveles aceptados";
  if (/profesional|pregrado|universitari/.test(detalle)) return "Profesional";
  if (/tecnico|tecnologo/.test(detalle)) return "Técnico o tecnólogo";
  if (/bachiller|operari|auxiliar/.test(detalle)) return "Auxiliar u operativo";
  return "No determinado";
}
function estadoSalario(vacante) {
  if (vacante.salario_minimo !== null && vacante.salario_minimo !== undefined) return "Publicado";
  if (/confidencial/i.test(texto(vacante.salario))) return "Confidencial";
  if (/convenir/i.test(texto(vacante.salario))) return "A convenir";
  if (/no informado/i.test(texto(vacante.salario))) return "No informado";
  return "No interpretable";
}
function modalidad(valor) {
  const dato = normalizar(valor);
  if (/hibrid|mixt/.test(dato)) return "Híbrida";
  if (/remot|virtual|teletrabajo/.test(dato)) return "Remota";
  if (/presencial/.test(dato)) return "Presencial";
  return "No informada";
}
function clasificarArea(cargo, descripcion) {
  const principal = normalizar(cargo);
  const apoyo = normalizar(descripcion).slice(0, 1800);
  const valor = principal + " " + apoyo;
  const reglas = [
    ["AE10", "Seguridad y salud en el trabajo", /\bsst\b|seguridad y salud|salud ocupacional/],
    ["AE03", "Inteligencia artificial, datos y ciberseguridad", /inteligencia artificial|analista de datos|cientifico de datos|ciberseguridad|business intelligence|analitica de datos/],
    ["AE02", "Tecnologías digitales y software", /software|desarrollador|programador|sistemas|devops|cloud|soporte ti|telecomunicaciones/],
    ["AE11", "Ambiente, sostenibilidad y cambio climático", /ambiental|sostenibilidad|forestal|cambio climatico/],
    ["AE12", "Bioeconomía, agroindustria y desarrollo rural", /agronom|agroindustr|agricol|pecuario|rural/],
    ["AE13", "Ciencias básicas e investigación", /investigacion|cientific|laboratorio|biolog|quimic|fisic/],
    ["AE01", "Educación y pedagogía", /docente|profesor|educacion|pedagog|academico/],
    ["AE05", "Infraestructura, construcción y territorio", /ingenieria civil|ingeniero civil|arquitect|construccion|obra/],
    ["AE16", "Logística, transporte y cadena de suministro", /logistic|transporte|cadena de suministro|almacen|bodega/],
    ["AE04", "Ingeniería, automatización e industria", /ingenier|automatizacion|produccion|mantenimiento|manufactura/],
    ["AE09", "Salud, psicología y bienestar", /medic|enfermer|psicolog|salud|nutricion|fisioterap/],
    ["AE08", "Derecho, gobierno y políticas públicas", /abogad|juridic|derecho|gobierno|politica publica/],
    ["AE14", "Desarrollo social y comunitario", /trabajo social|comunitari|desarrollo social/],
    ["AE15", "Comunicación, diseño e industrias creativas", /comunicador|comunicacion|disen|audiovisual|publicista|creativ/],
    ["AE17", "Turismo, cultura y servicios", /turismo|hotel|gastronom|cultura|viajes/],
    ["AE18", "Gestión de proyectos, calidad e innovación", /proyecto|calidad|innovacion|mejora continua/],
    ["AE06", "Administración, finanzas y economía", /administr|financier|contab|econom|tesorer|auditor/],
    ["AE07", "Mercadeo, ventas y emprendimiento", /mercadeo|marketing|comercial|ventas|emprendimiento/]
  ];
  for (const [codigo, area, patron] of reglas) if (patron.test(valor)) return { codigo, area };
  return { codigo: "OTR", area: "Otros perfiles regionales" };
}

for (let i = 0; i < respuestas.length; i++) {
  const respuesta = respuestas[i];
  const consulta = respuesta.query || consultas[i] || {};
  for (const original of (respuesta.vacancies || [])) {
    const regional = consulta.area_codigo === "REG";
    const clasificacion = regional
      ? clasificarArea(original.cargo, original.descripcion)
      : { codigo: consulta.area_codigo || original.area_codigo, area: consulta.area_estrategica || original.area_estrategica };
    const vacante = {
      ...original,
      id_consulta: consulta.id_consulta || original.id_consulta || "",
      area_codigo: clasificacion.codigo,
      area_estrategica: clasificacion.area,
      area_origen: consulta.area_estrategica || "",
      subarea: consulta.subarea || "",
      palabra_clave: consulta.palabra_clave || "",
      prioridad: consulta.prioridad || "",
      alcance_geografico: consulta.alcance_geografico || "Nacional",
      pagina_origen: "1",
      url_fuente: consulta.url || "",
      fuente_portal: "elempleo.com",
      nivel_ocupacional: nivel(original.cargo, original.descripcion, original.contrato),
      estado_salario: estadoSalario(original),
      modalidad_trabajo: modalidad(original.modalidad_trabajo),
      urgente: false
    };
    const clave = texto(vacante.fuente_registro_id) || texto(vacante.url_vacante) || [normalizar(vacante.cargo), normalizar(vacante.empresa), normalizar(vacante.ubicacion)].join("|");
