const municipiosTolima = ["Ibague","Alpujarra","Alvarado","Ambalema","Anzoategui","Armero Guayabal","Ataco","Cajamarca","Carmen de Apicala","Casabianca","Chaparral","Coello","Coyaima","Cunday","Dolores","Espinal","Falan","Flandes","Fresno","Guamo","Herveo","Honda","Icononzo","Lerida","Libano","San Sebastian de Mariquita","Mariquita","Melgar","Murillo","Natagaima","Ortega","Palocabildo","Piedras","Planadas","Prado","Purificacion","Rioblanco","Roncesvalles","Rovira","Saldana","San Antonio","San Luis","Santa Isabel","Suarez","Valle de San Juan","Venadillo","Villahermosa","Villarrica"];

function texto(valor) { return String(valor ?? "").trim(); }
function normalizar(valor) { return texto(valor).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, " ").trim(); }
function combinar(actual, nuevo) {
  const valores = new Set(texto(actual).split(" | ").filter(Boolean));
  if (texto(nuevo)) valores.add(texto(nuevo));
  return [...valores].join(" | ");
}
function fuente(valor) { return /elempleo/i.test(texto(valor)) ? "elempleo.com" : "Magneto"; }
function modalidad(valor) {
  const dato = normalizar(valor);
  if (/hibrid|mixt/.test(dato)) return "Híbrida";
  if (/remot|virtual|teletrabajo/.test(dato)) return "Remota";
  if (/presencial/.test(dato)) return "Presencial";
  if (/no disponible/.test(dato)) return "No disponible";
  return "No informada";
}
function ubicar(original) {
  const ubicacion = original.ubicacion;
  const dato = normalizar(ubicacion);
  const coincidencias = municipiosTolima.filter(m => dato.includes(normalizar(m))).sort((a,b) => b.length-a.length);
  const municipio = coincidencias[0] || "";
  const regional = Boolean(municipio || dato.includes("tolima") || Number(original.es_ibague_tolima) === 1);
  return {
    departamento: regional ? "Tolima" : (texto(original.departamento) || "No informado"),
    municipio: municipio || texto(original.municipio) || (/remot/.test(dato) ? "No informado" : texto(ubicacion) || "No informado"),
    regional: regional ? 1 : 0
  };
}
function estadoSalario(v) {
  if (v.salario_minimo !== null && v.salario_minimo !== undefined && v.salario_maximo !== null && v.salario_maximo !== undefined) return "Publicado";
  const dato = normalizar(v.salario);
  if (dato.includes("confidencial")) return "Confidencial";
  if (dato.includes("convenir")) return "A convenir";
  if (!dato || dato.includes("no informado")) return "No informado";
  return "No interpretable";
}

